class Solution:
    def sumConsecutiveSubarrays(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        ans = 0
        for i in range(n):
            cur = nums[i]
            ans += cur
            d = 0
            for j in range(i + 1, n):
                nd = nums[j] - nums[j - 1]
                if nd != 1 and nd != -1:
                    break
                if d != 0 and nd != d:
                    break
                d = nd
                cur += nums[j]
                ans += cur
        return ans % MOD

