class Solution {
public:
    int sumConsecutiveSubarrays(vector<int>& nums) {
        const long long MOD = 1000000007LL;
        long long ans = nums[0];
        long long length = 1, sumEnd = nums[0];
        int dPrev = 0;
        for (size_t i = 1; i < nums.size(); i++) {
            int d = nums[i] - nums[i - 1];
            if ((d == 1 || d == -1) && d == dPrev) {
                length++;
                sumEnd += length * nums[i];
            } else {
                length = 1;
                sumEnd = nums[i];
            }
            dPrev = (d == 1 || d == -1) ? d : 0;
            ans += sumEnd;
        }
        return (int)(ans % MOD);
    }
};

